body:
Jira Link: [DB-19350](https://yugabyte.atlassian.net/browse/DB-19350)
### Description

Version `2.29.0.0-b226`

Scenario:

```
CREATE TABLE _56_s_1 (
    id INT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    val TEXT
);

INSERT INTO _56_s_1 (val) VALUES ('a'), ('b');

SELECT id FROM _56_s_1 ORDER BY id;

BEGIN ISOLATION LEVEL REPEATABLE READ;

SAVEPOINT s1_start;

ALTER TABLE _56_s_1 ALTER COLUMN id RESTART WITH 100;
INSERT INTO _56_s_1 (val) VALUES ('c');

SELECT id FROM _56_s_1 WHERE val = 'c';

SAVEPOINT s2_restarted;

ALTER TABLE _56_s_1 ALTER COLUMN id DROP IDENTITY;
INSERT INTO _56_s_1 (id, val) VALUES (500, 'd');

ROLLBACK TO SAVEPOINT s2_restarted;

INSERT INTO _56_s_1 (val) VALUES ('e');

SELECT id FROM _56_s_1 WHERE val = 'e';
ROLLBACK TO SAVEPOINT s1_start;

INSERT INTO _56_s_1 (val) VALUES ('f');
SELECT id FROM _56_s_1 WHERE val = 'f';

COMMIT;
```

Failure:

```
yy=*# ROLLBACK TO SAVEPOINT s1_start;
ROLLBACK
yy=*# INSERT INTO _56_s_1 (val) VALUES ('f');
ERROR:  schema version mismatch for table 00004000000030008000000000004001: expected 4, got 3
```

